import sys
from itertools import combinations

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    K = int(data[2])

    board = []
    M = []

    index = 3
    for i in range(n):
        board.append(list(map(int, data[index:index + m])))
        index += m

    for i in range(n):
        M.append(list(map(int, data[index:index + m])))
        index += m

    return n, m, K, board, M

def is_valid_block(block, board, K):
    numbers = set()
    for x, y in block:
        if board[x][y] == -1:
            return False
        if board[x][y] > 0:
            numbers.add(board[x][y])
    return len(numbers) >= K

def bfs(start, board, visited):
    from collections import deque
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([start])
    visited[start[0]][start[1]] = True
    block = [start]

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(board) and 0 <= ny < len(board[0]) and not visited[nx][ny] and board[nx][ny] != -1:
                visited[nx][ny] = True
                block.append((nx, ny))
                queue.append((nx, ny))

    return block

def find_min_cost(n, m, K, board, M):
    min_cost = float('inf')
    found = False

    for i in range(n):
        for j in range(m):
            if board[i][j] != -1:
                visited = [[False] * m for _ in range(n)]
                block = bfs((i, j), board, visited)

                if is_valid_block(block, board, K):
                    cost = sum(M[x][y] for x, y in block)
                    if cost < min_cost:
                        min_cost = cost
                        found = True

    return min_cost if found else -1

def main():
    n, m, K, board, M = read_input()
    result = find_min_cost(n, m, K, board, M)
    print(result)

if __name__ == "__main__":
    main()
